#!/usr/bin/env python3
"""Writes make/builtin.q from stubs/*.stub (run it after editing a stub; CI checks it is up to date)."""
import glob
import os

root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
out = [
    '--" # The built-in stubs',
    '',
    'Generated by `scripts/embed_stubs.py` from `stubs/*.stub`: do not edit by hand.',
    '--"',
    '',
    'fun builtin_stubs() -> map<string, string>',
    '  let stubs: map<string, string> = {}',
]
for path in sorted(glob.glob(os.path.join(root, 'stubs', '*.stub'))):
    name = os.path.basename(path)[:-5]
    text = open(path).read().rstrip('\n')
    lines = []
    for line in text.split('\n'):
        esc = line.replace('\\', '\\\\').replace('"', '\\"').replace('{', '\\{').replace('}', '\\}')
        lines.append('"' + esc + '"')
    out.append('  stubs["%s"] = [' % name)
    for l in lines:
        out.append('    ' + l + ',')
    out.append('  ].join("\\n") + "\\n"')
out.append('  stubs')
out.append('end')
out.append('')
out.append('export builtin_stubs')
open(os.path.join(root, 'make', 'builtin.q'), 'w').write('\n'.join(out) + '\n')
